import json
import re
from collections import Counter

REPLACE_NONE = "None"

def task_func(json_str):
    data = json.loads(json_str)

    def remove_none(obj):
        if isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(item) for item in obj if item is not None]
        else:
            return obj

    cleaned_data = remove_none(data)

    def extract_values(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from extract_values(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from extract_values(item)
        else:
            yield obj

    all_values = list(extract_values(cleaned_data))
    value_counts = Counter(all_values)

    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b')
    def replace_emails(obj):
        if isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(item) for item in obj]
        elif isinstance(obj, str):
            return email_pattern.sub(REPLACE_NONE, obj)
        else:
            return obj

    final_data = replace_emails(cleaned_data)
    return {"data": final_data, "value_counts": value_counts}
