            new_dict = {}
            for k, v in item.items():
                if v is not None:
                    new_dict[k] = process_item(v)
            return new_dict
        elif isinstance(item, list):
            new_list = []
            for v in item:
                if v is not None:
                    new_list.append(process_item(v))
            return new_list
