                return REPLACE_NONE
            else:
                return item
        else:
            return item

    data = json.loads(json_str)
    processed_data = process_item(data)

    def extract_values(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(extract_values(v))
        elif isinstance(obj, list):
            for v in obj:
                values.extend(extract_values(v))
